"""RPC Talker Module"""

import time
import logging
import os


class RpcTalker:
    """RPC Talker class"""

    def __init__(self, connection, communication, protocol, logger=None):
        self.connection = connection
        self.communication = communication
        self.protocol = protocol
        self.logger = logging.getLogger(__name__) if logger is None else logger

    @staticmethod
    def load_rpc_from_file(rpc_directory, file_name: str):
        """
        Method to load RPC content from xml file
        :param: rpc_directory: directory
        :param: file_name: rpc file name
        """
        if not file_name.endswith(".xml"):
            file_name = f"{file_name}.xml"
        location = os.path.join(rpc_directory, file_name)
        with open(location) as xml_file:
            content = xml_file.read()
        if "rpc xmlns" not in content:
            raise AssertionError(f"Content:\n{content}\nis not proper RPC.")
        return f'{">".join(content.split(">")[1:-2])}>'

    def __call__(self, rpc_directory, session):  # noqa: C901
        """
        Start RPC Talker
        :param: router
        :param: protocol
        :param: rpc_directory
        :param: session
        """
        self.logger.debug(
            f"RPC talker was started.\nYou can define RPC messages as xml files in your directory: {rpc_directory}.\n"
            f"Available files or scenarios: {os.listdir(rpc_directory)}\n"
            f"Modifications are possible during runtime. Only ip addresses and ports defined in file are frozen.\n"
            f"If you need more than one instance for simulate sharing/concurrent you can run this script in separate"
            f" window.\n"
        )
        timeout = 180
        backup_rpc_directory = rpc_directory
        for sec in range(timeout):
            try:
                self.connection.call_home(session)
                break
            except OSError:
                time.sleep(sec)
                self.logger.debug("Try to establish call home ...")
        else:
            raise OSError(f"Not possible to achieve call home Timeout:{timeout}s exceeded.")
        while True:
            rpc_directory = backup_rpc_directory
            rpc_name = input(
                "\nType file name to send rpc or type 'exit' to finish script.\n"
                "If you would like to set more than one msg you can type name of subdirectory "
                "then whole content will be send.\n"
                "If you need check notifications buffer type 'noti': \n"
            )
            if rpc_name == "exit":
                self.connection.close_all_sessions()
                break
            if rpc_name == "noti":
                self.logger.debug(f"\nNotifications: {self.communication.collect_all_notifications(session)}\n")
                self.communication.clear_notifications_buffer_for_session(session)
                continue
            try:
                file_path = os.path.join(rpc_directory, rpc_name)
                if os.path.isdir(file_path):
                    files = os.listdir(file_path)
                    rpc_directory = file_path
                else:
                    files = [file_path]
                for file_name in files:
                    rpc_content = self.load_rpc_from_file(rpc_directory, file_name)
                    msg = {"request": rpc_content}
                    self.communication.send_rpc(session, msg, validation_mode="skip_validation")
            except (NameError, FileNotFoundError):
                self.logger.debug(
                    f"\nNot proper RPC file name. Try again.\n" f"Available files: {os.listdir(rpc_directory)}"
                )
            except Exception as exc:
                self.logger.debug(f"\nException raised: {exc}. Try again.\n")
